const items = $input.all();

const portfolio = {
  projects: [],
  actions: [],
  risks: [],
  issues: [],
  milestones: [],
  dependencies: []
};

// Original chat question
const userQuestion =
  $('User Question').first().json.question || "";

// Intent already classified before the Google Sheets branch
const queryContext =
  $('Classify User Intent').first().json.query_context || {
    original_question: userQuestion,
    intent: "GENERAL_PMO_QUERY",
    project_id: null
  };

for (const item of items) {
  const data = item.json;

  if (
    data["Project Name"] &&
    data["Health Score"] !== undefined
  ) {
    portfolio.projects.push(data);
    continue;
  }

  if (data["Action ID"]) {
    portfolio.actions.push(data);
    continue;
  }

  if (data["Risk ID"]) {
    portfolio.risks.push(data);
    continue;
  }

  if (data["Issue ID"]) {
    portfolio.issues.push(data);
    continue;
  }

  if (data["Milestone ID"]) {
    portfolio.milestones.push(data);
    continue;
  }

  if (data["Dependency ID"]) {
    portfolio.dependencies.push(data);
    continue;
  }
}

return [
  {
    json: {
      user_question: userQuestion,

      query_context: queryContext,

      portfolio,

      record_counts: {
        projects: portfolio.projects.length,
        actions: portfolio.actions.length,
        risks: portfolio.risks.length,
        issues: portfolio.issues.length,
        milestones: portfolio.milestones.length,
        dependencies: portfolio.dependencies.length
      }
    }
  }
];

const input = $input.first().json;

const portfolio = input.portfolio;
const exceptions = [];

const isBlank = (value) =>
  value === undefined ||
  value === null ||
  String(value).trim() === "";

const isYes = (value) =>
  String(value || "").trim().toLowerCase() === "yes";

const isOpen = (value) =>
  String(value || "").trim().toLowerCase() === "open";

const today = new Date("2026-08-12T00:00:00");

const projectMap = Object.fromEntries(
  portfolio.projects.map(project => [
    project["Project ID"],
    project
  ])
);

// 1. High Probability / High Impact or Risk Score 9 risks
// without required governance controls
for (const risk of portfolio.risks) {
  const highSeverity =
    Number(risk["Risk Score"]) >= 9 ||
    (
      String(risk["Probability"]).toLowerCase() === "high" &&
      String(risk["Impact"]).toLowerCase() === "high"
    );

  if (highSeverity && isOpen(risk["Status"])) {

    if (isBlank(risk["Owner"])) {
      exceptions.push({
        exception_type: "RISK_NO_OWNER",
        severity: "Critical",
        project_id: risk["Project ID"],
        record_id: risk["Risk ID"],
        description:
          "Open High Probability / High Impact risk with Risk Score 9 has no assigned owner."
      });
    }

    if (isBlank(risk["Mitigation"])) {
      exceptions.push({
        exception_type: "RISK_NO_MITIGATION",
        severity: "Critical",
        project_id: risk["Project ID"],
        record_id: risk["Risk ID"],
        description:
          "Open High Probability / High Impact risk with Risk Score 9 has no mitigation plan."
      });
    }

    if (!isYes(risk["Escalation Required"])) {
      exceptions.push({
        exception_type: "RISK_NOT_ESCALATED",
        severity: "High",
        project_id: risk["Project ID"],
        record_id: risk["Risk ID"],
        description:
          "Open High Probability / High Impact risk with Risk Score 9 is not marked for escalation."
      });
    }
  }
}

// 2. Critical issues without owner / escalation / overdue
for (const issue of portfolio.issues) {
  const critical =
    String(issue["Severity"]).toLowerCase() === "critical";

  if (critical && isOpen(issue["Status"])) {

    if (isBlank(issue["Owner"])) {
      exceptions.push({
        exception_type: "CRITICAL_ISSUE_NO_OWNER",
        severity: "Critical",
        project_id: issue["Project ID"],
        record_id: issue["Issue ID"],
        description:
          "Critical open issue has no assigned owner."
      });
    }

    if (!isYes(issue["Escalation Required"])) {
      exceptions.push({
        exception_type: "CRITICAL_ISSUE_NOT_ESCALATED",
        severity: "Critical",
        project_id: issue["Project ID"],
        record_id: issue["Issue ID"],
        description:
          "Critical open issue is not marked for escalation."
      });
    }

    const targetDateRaw = issue["Target Resolution Date"];

    if (targetDateRaw) {
      const targetDate =
        new Date(`${targetDateRaw}T00:00:00`);

      if (targetDate < today) {
        exceptions.push({
          exception_type: "CRITICAL_ISSUE_OVERDUE",
          severity: "Critical",
          project_id: issue["Project ID"],
          record_id: issue["Issue ID"],
          description:
            "Critical open issue is past its target resolution date."
        });
      }
    }
  }
}

// 3. Green project with Critical open issue
for (const project of portfolio.projects) {
  const projectId = project["Project ID"];

  const criticalOpenIssue =
    portfolio.issues.some(issue =>
      issue["Project ID"] === projectId &&
      String(issue["Severity"]).toLowerCase() === "critical" &&
      isOpen(issue["Status"])
    );

  if (
    String(project["Overall Status"]).toLowerCase() === "green" &&
    criticalOpenIssue
  ) {
    exceptions.push({
      exception_type: "GREEN_STATUS_CONTRADICTION",
      severity: "Critical",
      project_id: projectId,
      record_id: projectId,
      description:
        "Project is reported Green despite having a Critical open issue."
    });
  }
}

// 4. Critical milestones that are delayed or at risk
for (const milestone of portfolio.milestones) {
  const critical =
    String(
      milestone["Critical Milestone"]
    ).toLowerCase() === "yes";

  const status =
    String(milestone["Status"]).toLowerCase();

  if (
    critical &&
    (
      status === "delayed" ||
      status === "at risk"
    )
  ) {
    exceptions.push({
      exception_type: "CRITICAL_MILESTONE_AT_RISK",
      severity:
        status === "delayed"
          ? "High"
          : "Medium",
      project_id: milestone["Project ID"],
      record_id: milestone["Milestone ID"],
      description:
        `Critical milestone is ${milestone["Status"]}.`
    });
  }
}

// Add project name
for (const exception of exceptions) {
  exception.project_name =
    projectMap[
      exception.project_id
    ]?.["Project Name"] || "";
}

return [
  {
    json: {
      user_question: input.user_question,
      query_context: input.query_context,

      portfolio,

      record_counts: input.record_counts,

      governance_exceptions: exceptions,

      governance_summary: {
        total_exceptions: exceptions.length,

        critical:
          exceptions.filter(
            x => x.severity === "Critical"
          ).length,

        high:
          exceptions.filter(
            x => x.severity === "High"
          ).length,

        medium:
          exceptions.filter(
            x => x.severity === "Medium"
          ).length
      }
    }
  }
];

const input = $input.first().json;

function extractText(payload) {
  if (Array.isArray(payload.output)) {
    for (const message of payload.output) {
      if (!Array.isArray(message.content)) continue;

      for (const part of message.content) {
        if (
          part.type === "output_text" &&
          typeof part.text === "string"
        ) {
          return part.text;
        }
      }
    }
  }

  if (typeof payload.text === "string") {
    return payload.text;
  }

  if (typeof payload.response === "string") {
    return payload.response;
  }

  if (typeof payload.content === "string") {
    return payload.content;
  }

  throw new Error("AI response text could not be found.");
}

const rawText = extractText(input).trim();

let parsed;

try {
  parsed = JSON.parse(rawText);
} catch (error) {
  throw new Error(
    `AI PMO response is not valid JSON. Parse error: ${error.message}`
  );
}

const requiredTopLevelFields = [
  "query_response",
  "executive_summary",
  "portfolio_assessment",
  "project_deep_dive",
  "top_concerns",
  "governance_findings",
  "recommended_management_actions",
  "executive_attention_required"
];

const missingFields = requiredTopLevelFields.filter(
  field => !(field in parsed)
);

if (missingFields.length > 0) {
  throw new Error(
    `AI PMO response is missing required fields: ${missingFields.join(", ")}`
  );
}

// -----------------------------
// Top-level validation
// -----------------------------

if (
  typeof parsed.query_response !== "object" ||
  parsed.query_response === null ||
  typeof parsed.executive_summary !== "string" ||
  typeof parsed.portfolio_assessment !== "object" ||
  parsed.portfolio_assessment === null ||
  typeof parsed.project_deep_dive !== "object" ||
  parsed.project_deep_dive === null ||
  !Array.isArray(parsed.top_concerns) ||
  !Array.isArray(parsed.governance_findings) ||
  !Array.isArray(parsed.recommended_management_actions) ||
  typeof parsed.executive_attention_required !== "boolean"
) {
  throw new Error(
    "AI PMO response contains invalid top-level field types."
  );
}

// -----------------------------
// query_response validation
// -----------------------------

const queryResponseRequired = [
  "original_question",
  "intent",
  "target_project_id"
];

const missingQueryFields =
  queryResponseRequired.filter(
    field => !(field in parsed.query_response)
  );

if (missingQueryFields.length > 0) {
  throw new Error(
    `query_response is missing required fields: ${missingQueryFields.join(", ")}`
  );
}

if (
  typeof parsed.query_response.original_question !== "string" ||
  typeof parsed.query_response.intent !== "string" ||
  !(
    typeof parsed.query_response.target_project_id === "string" ||
    parsed.query_response.target_project_id === null
  )
) {
  throw new Error(
    "query_response contains invalid field types."
  );
}

// -----------------------------
// portfolio_assessment validation
// -----------------------------

if (
  typeof parsed.portfolio_assessment.overall_health !== "string" ||
  !Array.isArray(
    parsed.portfolio_assessment.projects_requiring_attention
  )
) {
  throw new Error(
    "portfolio_assessment contains invalid field types."
  );
}

// -----------------------------
// project_deep_dive validation
// -----------------------------

const deepDiveRequired = [
  "project_id",
  "project_name",
  "overall_status",
  "health_score",
  "health_band",
  "schedule_status",
  "cost_status",
  "scope_status",
  "risk_status",
  "actions",
  "risks",
  "issues",
  "milestones",
  "dependencies"
];

const missingDeepDiveFields =
  deepDiveRequired.filter(
    field => !(field in parsed.project_deep_dive)
  );

if (missingDeepDiveFields.length > 0) {
  throw new Error(
    `project_deep_dive is missing required fields: ${missingDeepDiveFields.join(", ")}`
  );
}

if (
  !(
    typeof parsed.project_deep_dive.project_id === "string" ||
    parsed.project_deep_dive.project_id === null
  ) ||
  typeof parsed.project_deep_dive.project_name !== "string" ||
  typeof parsed.project_deep_dive.overall_status !== "string" ||
  !(
    typeof parsed.project_deep_dive.health_score === "number" ||
    parsed.project_deep_dive.health_score === null
  ) ||
  typeof parsed.project_deep_dive.health_band !== "string" ||
  typeof parsed.project_deep_dive.schedule_status !== "string" ||
  typeof parsed.project_deep_dive.cost_status !== "string" ||
  typeof parsed.project_deep_dive.scope_status !== "string" ||
  typeof parsed.project_deep_dive.risk_status !== "string" ||
  !Array.isArray(parsed.project_deep_dive.actions) ||
  !Array.isArray(parsed.project_deep_dive.risks) ||
  !Array.isArray(parsed.project_deep_dive.issues) ||
  !Array.isArray(parsed.project_deep_dive.milestones) ||
  !Array.isArray(parsed.project_deep_dive.dependencies)
) {
  throw new Error(
    "project_deep_dive contains invalid field types."
  );
}

// -----------------------------
// top_concerns validation
// -----------------------------

for (const item of parsed.top_concerns) {
  if (
    typeof item.priority !== "string" ||
    typeof item.project_id !== "string" ||
    typeof item.record_id !== "string" ||
    typeof item.concern !== "string" ||
    typeof item.business_implication !== "string"
  ) {
    throw new Error(
      "top_concerns contains an invalid item."
    );
  }
}

// -----------------------------
// governance_findings validation
// -----------------------------

for (const item of parsed.governance_findings) {
  if (
    typeof item.severity !== "string" ||
    typeof item.project_id !== "string" ||
    typeof item.record_id !== "string" ||
    typeof item.finding !== "string"
  ) {
    throw new Error(
      "governance_findings contains an invalid item."
    );
  }
}

// -----------------------------
// recommended_management_actions validation
// -----------------------------

for (
  const item of parsed.recommended_management_actions
) {
  if (
    typeof item.priority !== "string" ||
    typeof item.project_id !== "string" ||
    typeof item.action !== "string" ||
    typeof item.reason !== "string"
  ) {
    throw new Error(
      "recommended_management_actions contains an invalid item."
    );
  }
}

// -----------------------------
// Project-specific scope validation
// -----------------------------

const projectSpecificIntents = [
  "PROJECT_DEEP_DIVE",
  "PROJECT_RISK_QUERY",
  "PROJECT_ISSUE_QUERY",
  "PROJECT_ACTION_QUERY",
  "PROJECT_MILESTONE_QUERY",
  "PROJECT_GOVERNANCE_QUERY"
];

const intent = parsed.query_response.intent;
const targetProjectId =
  parsed.query_response.target_project_id;

if (projectSpecificIntents.includes(intent)) {
  if (!targetProjectId) {
    throw new Error(
      "Project-specific intent requires target_project_id."
    );
  }

  if (
    parsed.project_deep_dive.project_id !== null &&
    parsed.project_deep_dive.project_id !== targetProjectId
  ) {
    throw new Error(
      "project_deep_dive.project_id does not match target_project_id."
    );
  }

  const invalidConcerns =
    parsed.top_concerns.filter(
      item => item.project_id !== targetProjectId
    );

  if (invalidConcerns.length > 0) {
    throw new Error(
      "top_concerns contains records outside the target project."
    );
  }

  const invalidFindings =
    parsed.governance_findings.filter(
      item => item.project_id !== targetProjectId
    );

  if (invalidFindings.length > 0) {
    throw new Error(
      "governance_findings contains records outside the target project."
    );
  }

  const invalidActions =
    parsed.recommended_management_actions.filter(
      item => item.project_id !== targetProjectId
    );

  if (invalidActions.length > 0) {
    throw new Error(
      "recommended_management_actions contains records outside the target project."
    );
  }

  const attentionProjects =
    parsed.portfolio_assessment
      .projects_requiring_attention;

  const invalidAttentionProjects =
    attentionProjects.filter(
      projectId => projectId !== targetProjectId
    );

  if (invalidAttentionProjects.length > 0) {
    throw new Error(
      "projects_requiring_attention contains unrelated projects for a project-specific query."
    );
  }
}

// -----------------------------
// Return validated structure
// -----------------------------

return [
  {
    json: {
      ai_response_valid: true,
      validation_status: "PASSED",

      query_response:
        parsed.query_response,

      executive_summary:
        parsed.executive_summary,

      portfolio_assessment:
        parsed.portfolio_assessment,

      project_deep_dive:
        parsed.project_deep_dive,

      top_concerns:
        parsed.top_concerns,

      governance_findings:
        parsed.governance_findings,

      recommended_management_actions:
        parsed.recommended_management_actions,

      executive_attention_required:
        parsed.executive_attention_required,

      parsed_ai_response:
        parsed
    }
  }
];

const data = $input.first().json;

if (
  data.validation_status !== "PASSED" ||
  data.ai_response_valid !== true
) {
  throw new Error("AI PMO response has not passed validation.");
}

const query = data.query_response || {};
const intent = query.intent || "GENERAL_PMO_QUERY";
const targetProjectId = query.target_project_id || null;

const summary = data.executive_summary || "";
const assessment = data.portfolio_assessment || {};
const deepDive = data.project_deep_dive || {};

const concerns = Array.isArray(data.top_concerns)
  ? data.top_concerns
  : [];

const findings = Array.isArray(data.governance_findings)
  ? data.governance_findings
  : [];

const actions = Array.isArray(
  data.recommended_management_actions
)
  ? data.recommended_management_actions
  : [];

const attentionRequired =
  data.executive_attention_required === true;

const projectSpecificIntents = [
  "PROJECT_DEEP_DIVE",
  "PROJECT_RISK_QUERY",
  "PROJECT_ISSUE_QUERY",
  "PROJECT_ACTION_QUERY",
  "PROJECT_MILESTONE_QUERY",
  "PROJECT_GOVERNANCE_QUERY"
];

const isProjectSpecific =
  projectSpecificIntents.includes(intent);

// --------------------------------------------------
// Helpers
// --------------------------------------------------

function field(item, ...keys) {
  for (const key of keys) {
    if (
      item &&
      item[key] !== undefined &&
      item[key] !== null &&
      item[key] !== ""
    ) {
      return item[key];
    }
  }

  return "";
}

function safe(value, fallback = "") {
  if (
    value === undefined ||
    value === null ||
    value === ""
  ) {
    return fallback;
  }

  return String(value);
}

function normalizePriority(value) {
  const raw = String(value || "")
    .trim()
    .toLowerCase();

  if (
    raw === "p1" ||
    raw.includes("critical") ||
    raw.includes("highest") ||
    raw.includes("immediate") ||
    raw === "1" ||
    raw.startsWith("1 ")
  ) {
    return "Critical";
  }

  if (
    raw === "p2" ||
    raw.includes("high") ||
    raw === "2" ||
    raw.startsWith("2 ")
  ) {
    return "High";
  }

  if (
    raw === "p3" ||
    raw.includes("medium") ||
    raw === "3" ||
    raw.startsWith("3 ")
  ) {
    return "Medium";
  }

  if (
    raw === "p4" ||
    raw === "4" ||
    raw.startsWith("4 ") ||
    raw.includes("low")
  ) {
    return "Low";
  }

  if (
    raw === "p5" ||
    raw === "5" ||
    raw.startsWith("5 ")
  ) {
    return "Low";
  }

  return safe(value, "Medium");
}

function addSection(lines, title) {
  lines.push("");
  lines.push(`## ${title}`);
  lines.push("");
}

// --------------------------------------------------
// Record formatting
// --------------------------------------------------

function addRecordList(lines, records, type) {
  if (
    !Array.isArray(records) ||
    records.length === 0
  ) {
    lines.push(
      `No ${type.toLowerCase()} records returned.`
    );
    return;
  }

  records.forEach((item, index) => {

    // ---------------- ACTION ----------------

    if (type === "ACTION") {
      const id = field(
        item,
        "Action ID",
        "action_id"
      );

      const description = field(
        item,
        "Action",
        "action"
      );

      const priority = field(
        item,
        "Priority",
        "priority"
      );

      const status = field(
        item,
        "Status",
        "status"
      );

      const owner = field(
        item,
        "Owner",
        "owner"
      );

      const dueDate = field(
        item,
        "Due Date",
        "due_date"
      );

      const escalation = field(
        item,
        "Escalation Required",
        "escalation_required"
      );

      lines.push(
        `${index + 1}. **${safe(id, "Unknown Action")} — ${safe(description, "No description")}**`
      );

      lines.push(
        `   Priority: ${safe(priority, "Not specified")} | Status: ${safe(status, "Not specified")}`
      );

      lines.push(
        `   Owner: ${safe(owner, "Not assigned")} | Due: ${safe(dueDate, "Not specified")}`
      );

      lines.push(
        `   Escalation Required: ${safe(escalation, "Not specified")}`
      );

      lines.push("");
    }

    // ---------------- RISK ----------------

    if (type === "RISK") {
      const id = field(
        item,
        "Risk ID",
        "risk_id"
      );

      const description = field(
        item,
        "Risk",
        "risk"
      );

      const probability = field(
        item,
        "Probability",
        "probability"
      );

      const impact = field(
        item,
        "Impact",
        "impact"
      );

      const score = field(
        item,
        "Risk Score",
        "risk_score"
      );

      const status = field(
        item,
        "Status",
        "status"
      );

      const owner = field(
        item,
        "Owner",
        "owner"
      );

      const mitigation = field(
        item,
        "Mitigation",
        "mitigation"
      );

      const escalation = field(
        item,
        "Escalation Required",
        "escalation_required"
      );

      lines.push(
        `${index + 1}. **${safe(id, "Unknown Risk")} — ${safe(description, "No description")}**`
      );

      lines.push(
        `   Probability: ${safe(probability, "Not specified")} | Impact: ${safe(impact, "Not specified")} | Risk Score: ${safe(score, "Not specified")}`
      );

      lines.push(
        `   Status: ${safe(status, "Not specified")} | Owner: ${safe(owner, "Not assigned")}`
      );

      lines.push(
        `   Mitigation: ${safe(mitigation, "Not defined")}`
      );

      lines.push(
        `   Escalation Required: ${safe(escalation, "Not specified")}`
      );

      lines.push("");
    }

    // ---------------- ISSUE ----------------

    if (type === "ISSUE") {
      const id = field(
        item,
        "Issue ID",
        "issue_id"
      );

      const description = field(
        item,
        "Issue",
        "issue"
      );

      const severity = field(
        item,
        "Severity",
        "severity"
      );

      const status = field(
        item,
        "Status",
        "status"
      );

      const owner = field(
        item,
        "Owner",
        "owner"
      );

      const targetDate = field(
        item,
        "Target Resolution Date",
        "target_resolution_date"
      );

      const businessImpact = field(
        item,
        "Business Impact",
        "business_impact"
      );

      const escalation = field(
        item,
        "Escalation Required",
        "escalation_required"
      );

      lines.push(
        `${index + 1}. **${safe(id, "Unknown Issue")} — ${safe(description, "No description")}**`
      );

      lines.push(
        `   Severity: ${safe(severity, "Not specified")} | Status: ${safe(status, "Not specified")}`
      );

      lines.push(
        `   Owner: ${safe(owner, "Not assigned")} | Target Resolution: ${safe(targetDate, "Not specified")}`
      );

      lines.push(
        `   Business Impact: ${safe(businessImpact, "Not specified")}`
      );

      lines.push(
        `   Escalation Required: ${safe(escalation, "Not specified")}`
      );

      lines.push("");
    }

    // ---------------- MILESTONE ----------------

    if (type === "MILESTONE") {
      const id = field(
        item,
        "Milestone ID",
        "milestone_id"
      );

      const description = field(
        item,
        "Milestone",
        "milestone"
      );

      const plannedDate = field(
        item,
        "Planned Date",
        "planned_date"
      );

      const forecastDate = field(
        item,
        "Forecast Date",
        "forecast_date"
      );

      const status = field(
        item,
        "Status",
        "status"
      );

      const criticalMilestone = field(
        item,
        "Critical Milestone",
        "critical_milestone"
      );

      const owner = field(
        item,
        "Owner",
        "owner"
      );

      lines.push(
        `${index + 1}. **${safe(id, "Unknown Milestone")} — ${safe(description, "No description")}**`
      );

      lines.push(
        `   Planned: ${safe(plannedDate, "Not specified")} | Forecast: ${safe(forecastDate, "Not specified")}`
      );

      lines.push(
        `   Status: ${safe(status, "Not specified")} | Critical Milestone: ${safe(criticalMilestone, "Not specified")}`
      );

      lines.push(
        `   Owner: ${safe(owner, "Not assigned")}`
      );

      lines.push("");
    }

    // ---------------- DEPENDENCY ----------------

    if (type === "DEPENDENCY") {
      const id = field(
        item,
        "Dependency ID",
        "dependency_id"
      );

      const description = field(
        item,
        "Dependency",
        "dependency"
      );

      const dependencyType = field(
        item,
        "Dependency Type",
        "dependency_type"
      );

      const status = field(
        item,
        "Status",
        "status"
      );

      const dependentOn = field(
        item,
        "Dependent On",
        "dependent_on"
      );

      const owner = field(
        item,
        "Owner",
        "owner"
      );

      const requiredBy = field(
        item,
        "Required By Date",
        "required_by_date"
      );

      const impactIfDelayed = field(
        item,
        "Impact if Delayed",
        "impact_if_delayed"
      );

      lines.push(
        `${index + 1}. **${safe(id, "Unknown Dependency")} — ${safe(description, "No description")}**`
      );

      lines.push(
        `   Type: ${safe(dependencyType, "Not specified")} | Status: ${safe(status, "Not specified")}`
      );

      lines.push(
        `   Dependent On: ${safe(dependentOn, "Not specified")}`
      );

      lines.push(
        `   Owner: ${safe(owner, "Not assigned")} | Required By: ${safe(requiredBy, "Not specified")}`
      );

      lines.push(
        `   Impact if Delayed: ${safe(impactIfDelayed, "Not specified")}`
      );

      lines.push("");
    }
  });
}

