    );
  }

  // ISSUES
  if (
    intent === "PROJECT_DEEP_DIVE" ||
    intent === "PROJECT_ISSUE_QUERY"
  ) {
    addSection(
      lines,
      "Issues"
    );

    addRecordList(
      lines,
      deepDive.issues,
      "ISSUE"
    );
  }

  // MILESTONES
  if (
