        attentionRequired,

      executive_briefing:
        executiveBriefing,

      executive_summary:
        summary,

      portfolio_assessment:
        assessment,

      project_deep_dive:
        deepDive,

      top_concerns:
        concerns,

      governance_findings:
        findings,

      recommended_management_actions:
        actions
    }
  }
];

const input = $input.first().json;

const originalQuestion = String(input.question || "").trim();
const question = originalQuestion.toLowerCase();

let intent = "GENERAL_PMO_QUERY";
let project_id = null;

// Detect Project ID
const projectMatch = question.match(/\bprj-\d+\b/i);

if (projectMatch) {
  project_id = projectMatch[0].toUpperCase();
}

// Casual conversation
const casualGreetings = [
  "hello",
  "hi",
  "hey",
  "good morning",
  "good afternoon",
  "good evening",
  "how are you",
  "thanks",
  "thank you"
];

if (
  casualGreetings.includes(question) ||
  question.startsWith("hello ") ||
  question.startsWith("hi ") ||
  question.startsWith("hey ")
) {
  intent = "CASUAL_CONVERSATION";
}

// Portfolio summary
else if (
  question.includes("executive portfolio summary") ||
  question.includes("portfolio summary") ||
  question.includes("executive summary") ||
  question.includes("portfolio health")
) {
  intent = "PORTFOLIO_SUMMARY";
}

// Project deep dive
else if (
  project_id &&
  (
    question.includes("deep dive") ||
    question.includes("project status") ||
    question.includes("tell me about") ||
    question.includes("summary") ||
    question.includes("health")
  )
) {
  intent = "PROJECT_DEEP_DIVE";
}

// Risk queries
else if (
  question.includes("risk") ||
  question.includes("risks")
) {
  intent = project_id
    ? "PROJECT_RISK_QUERY"
    : "PORTFOLIO_RISK_QUERY";
}

// Issue queries
else if (
  question.includes("issue") ||
  question.includes("issues")
) {
  intent = project_id
    ? "PROJECT_ISSUE_QUERY"
    : "PORTFOLIO_ISSUE_QUERY";
}

// Action queries
else if (
  question.includes("action") ||
  question.includes("actions") ||
  question.includes("overdue")
) {
  intent = project_id
    ? "PROJECT_ACTION_QUERY"
    : "PORTFOLIO_ACTION_QUERY";
}

// Milestone queries
else if (
  question.includes("milestone") ||
  question.includes("milestones") ||
  question.includes("schedule") ||
  question.includes("delayed")
) {
  intent = project_id
    ? "PROJECT_MILESTONE_QUERY"
    : "PORTFOLIO_MILESTONE_QUERY";
}

// Governance queries
else if (
  question.includes("governance") ||
  question.includes("exception") ||
  question.includes("exceptions") ||
  question.includes("contradiction")
) {
  intent = project_id
    ? "PROJECT_GOVERNANCE_QUERY"
    : "PORTFOLIO_GOVERNANCE_QUERY";
}

// Any other project-specific question
else if (project_id) {
  intent = "PROJECT_DEEP_DIVE";
}

return [
  {
    json: {
      ...input,
      query_context: {
        original_question: originalQuestion,
        intent,
        project_id
      }
    }
  }
];
